{
  "artifact_id": "LIVE-TEACH-CLAMP-comparison",
  "revision": "r1",
  "task_id": "LIVE-TEACH-CLAMP",
  "task_revision": "t1",
  "type": "ComparisonRecord",
  "scope": "Teaching comparison frame and test-planning record only. M01 is a provisional datum, not an approved or demonstrated clamp. Performance comparisons stop because retention conditions and damage criteria are undefined. No concept is recommended, tested or engineering validated.",
  "conditions": [
    {
      "id": "C01",
      "text": "The supplied task seeks a bench clamp that holds a workpiece without damage. REQ01 and REQ02 remain proposed; customer requirement hardness remains unknown.",
      "kind": "fact",
      "evidence_refs": []
    },
    {
      "id": "C02",
      "text": "Use M01, the manual screw route, as a provisional teaching datum and compare M02, the pneumatic route. This datum choice is a planning assumption, not a customer preference.",
      "kind": "assumption",
      "evidence_refs": []
    },
    {
      "id": "C03",
      "text": "The Boolean hard field below describes a proposed procedural gate for permitting selection, not the unknown hardness of customer requirements. Unknown customer hardness is not represented as false.",
      "kind": "assumption",
      "evidence_refs": []
    },
    {
      "id": "C04",
      "text": "M03 remains conditionally excluded under its supplied topology: its release option requires a screw transmission that its closing option explicitly omits. This logical conflict establishes no performance result for M01 or M02.",
      "kind": "fact",
      "evidence_refs": []
    },
    {
      "id": "C05",
      "text": "The lunar-sampling excerpt has unestablished transferability and supplies neither customer clamp parameters nor evidence of clamp performance.",
      "kind": "fact",
      "evidence_refs": [
        "case-98b73a9c96af1f9408721571"
      ]
    }
  ],
  "evidence_refs": [
    "case-98b73a9c96af1f9408721571"
  ],
  "payload": {
    "baseline_id": "M01",
    "candidate_ids": [
      "M02"
    ],
    "criteria": [
      {
        "id": "G01",
        "text": "Proposed selection-readiness gate: establish applicable constraints and demonstrate retention and acceptable workpiece condition against stakeholder-defined use conditions before recommending a route. This procedural gate does not assign hardness to REQ01 or REQ02.",
        "hard": true
      }
    ],
    "judgments": [
      {
        "candidate_id": "M02",
        "criterion_id": "G01",
        "value": "unknown",
        "basis": "Record author: planning assessment from supplied inputs only. Loads, material, geometry, allowable movement, damage limits and requirement authority are unknown. Neither M02 nor datum M01 has evidence establishing this gate. Their shared contact-management option does not establish equivalent damage or retention performance. No relative performance score is justified.",
        "evidence_refs": []
      }
    ],
    "recommendations": [],
    "sensitivity": [
      "Datum choice cannot resolve missing acceptance criteria. Switching the datum to M02 would leave selection readiness unknown.",
      "M01 assumes manual input and hypothesized screw-position retention; M02 assumes pneumatic supply, sustained input and elastic return. Resource availability and acceptable input-loss behavior could change which routes merit further investigation.",
      "Contact geometry, material and surface interaction could change retention and damage together. No ranking, weights or symbol totals are justified."
    ],
    "unknowns": [
      "Confirm the intended work operation, operator capabilities, bench interface and available actuation resources.",
      "Define representative workpiece materials, finishes, geometries and variation.",
      "Establish loads, directions, holding duration and allowable movement; agree what constitutes damage and how it will be assessed.",
      "Identify requirement owners and confirmation authority; determine customer requirement hardness without treating the proposed procedural gate as approval.",
      "After criteria are defined, plan comparisons under common workpiece and loading conditions, including engagement, holding, release and before-and-after condition assessment. Procedures, thresholds, sample counts and resources remain to be defined; nothing has been executed.",
      "For M01, plan investigation of restraint persistence, disturbance sensitivity and reverse-screw release. For M02, plan investigation of sustained supply, intentional venting, return behavior and supply loss.",
      "Reopen the Pugh performance matrix only after its criteria and supporting evidence are sufficiently defined. Retain both routes as unresolved teaching hypotheses, without a preferred concept."
    ]
  }
}
